    const sourceW=Math.max(1,els.overlay.width),sourceH=Math.max(1,els.overlay.height),maxSide=sourceMode==="upload"?960:1280,scale=Math.min(1,maxSide/Math.max(sourceW,sourceH));
    recordCanvas.width=Math.max(2,Math.round(sourceW*scale));recordCanvas.height=Math.max(2,Math.round(sourceH*scale));
    const captureFps=sourceMode==="upload"?UPLOAD_RECORD_FPS:20,compositeStream=recordCanvas.captureStream?.(captureFps),recordStream=compositeStream||stream;
    if(!recordStream)throw new Error("captureStream unavailable");
