    const candidates=["video/mp4;codecs=avc1","video/webm;codecs=vp9","video/webm;codecs=vp8","video/webm"],mimeType=candidates.find(type=>MediaRecorder.isTypeSupported?.(type)),options=mimeType?{mimeType,videoBitsPerSecond:sourceMode==="upload"?1200000:2200000}:{videoBitsPerSecond:sourceMode==="upload"?1200000:2200000};
