function trackROI(w,h){if(!els.video.videoWidth)return;roiCanvas.width=Math.max(1,Math.round(w));roiCanvas.height=Math.max(1,Math.round(h));roiCtx.drawImage(els.video,0,0,w,h);const frame=roiCtx.getImageData(0,0,roiCanvas.width,roiCanvas.height).data;if(!roiTemplate){roiTemplate=grayPatch(frame,roiCanvas.width,roi.x,roi.y);roi.score=1;return}let best={sad:Infinity,x:roi.x,y:roi.y};for(let dy=-8;dy<=8;dy+=2)for(let dx=-8;dx<=8;dx+=2){const patch=grayPatch(frame,roiCanvas.width,roi.x+dx,roi.y+dy);let sad=0;for(let i=0;i<patch.length;i++)sad+=Math.abs(patch[i]-roiTemplate[i]);if(sad<best.sad)best={sad,x:roi.x+dx,y:roi.y+dy}}roi.x=Math.max(18,Math.min(w-18,best.x));roi.y=Math.max(18,Math.min(h-18,best.y));roi.score=Math.max(0,Math.min(1,1-best.sad/(roiTemplate.length*55)));if(roi.score>.72){const fresh=grayPatch(frame,roiCanvas.width,roi.x,roi.y);for(let i=0;i<fresh.length;i++)roiTemplate[i]=Math.round(roiTemplate[i]*.96+fresh[i]*.04)}}
