function startCountdown(){if(!running||sessionActive||countdownActive)return;if(!roi){els.stageGuide.classList.add("attention");els.stageGuide.textContent="請先在影像中點選槍口／準星位置，再按開始分析";return}session=[];sessionBaseline=null;reportSummary=null;sessionFrame=null;timelineAnalysis=null;clearReplay();drawTrace([]);els.reportButton.disabled=true;els.shareButton.disabled=true;els.exportButton.disabled=true;els.reportStatus.textContent="";els.resultsContent.classList.add("hidden");els.resultsEmpty.classList.remove("hidden");if(sourceMode==="upload"){activeSessionSeconds=importedRange.end-importedRange.start;beginSession();return}activeSessionSeconds=SESSION_SECONDS;countdownActive=true;updateStartAvailability();els.sessionState.textContent="準備倒數";els.sessionDot.style.background="var(--amber)";els.countdownOverlay.classList.remove("hidden");let remaining=COUNTDOWN_SECONDS;const tick=()=>{els.countdownValue.textContent=String(remaining);els.sessionClock.textContent=`00:0${remaining}.0`;els.sessionButton.querySelector("span").textContent=`準備倒數 ${remaining}`;if(remaining===0){beginSession();return}remaining-=1;countdownTimer=setTimeout(tick,1000)};tick()}
