function roundedRect(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.stroke()}}
function wrapText(c,text,x,y,maxWidth,lineHeight,maxLines=4){const chars=[...text],lines=[];let line="";for(const char of chars){const test=line+char;if(c.measureText(test).width>maxWidth&&line){lines.push(line);line=char}else line=test}if(line)lines.push(line);lines.slice(0,maxLines).forEach((value,i)=>c.fillText(value,x,y+i*lineHeight))}
