function reportFilename(){const stamp=(reportSummary?.createdAt||new Date()).toISOString().replace(/[:.]/g,"-");return`AimTrace-檢測報告-${stamp}.png`}function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
