function downloadReplay(){if(!replayBlob)return;downloadBlob(replayBlob,replayFilename());els.replayStatus.textContent=`回放影片已下載（${replayBlob.type.includes("mp4")?"MP4":"WebM"}）。`}
async function shareReplay(){if(!replayBlob)return;try{const file=new File([replayBlob],replayFilename(),{type:replayBlob.type||"video/webm"});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({title:"AimTrace 空氣手槍分析回放",text:`這是本次 AimTrace ${activeSessionSeconds.toFixed(1)} 秒骨架、軌跡與即時數據分析回放，請在分享選單選擇 LINE。`,files:[file]});els.replayStatus.textContent="已開啟影片分享選單。"}else{downloadBlob(replayBlob,file.name);els.replayStatus.textContent="此瀏覽器無法直接分享影片；檔案已下載，請在 LINE 中手動選取。"}}catch(error){if(error.name==="AbortError")els.replayStatus.textContent="已取消影片分享。";else{downloadBlob(replayBlob,replayFilename());els.replayStatus.textContent=`影片分享失敗，已改為下載：${error.message}`}}}
async function downloadReport(){try{els.reportStatus.className="report-status";els.reportStatus.textContent="正在產生教練完整檢測報告…";const blob=await createCoachReportBlob();downloadBlob(blob,reportFilename());els.reportStatus.textContent="教練完整檢測報告已下載。"}catch(error){els.reportStatus.className="report-status error";els.reportStatus.textContent=error.message}}
async function shareReport(){try{els.reportStatus.className="report-status";els.reportStatus.textContent="正在準備 LINE 教練完整報告…";const blob=await createCoachReportBlob(),file=new File([blob],reportFilename(),{type:"image/png"});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({title:"AimTrace 空氣手槍教練完整檢測報告",text:`這是本次 AimTrace ${reportSummary.duration.toFixed(1)} 秒教練完整報告，含 ROI 軌跡、穩定度時間軸、追蹤品質與射擊階段影像推估，請在分享選單選擇 LINE。`,files:[file]});els.reportStatus.textContent="已開啟分享選單。"}else{downloadBlob(blob,file.name);els.reportStatus.className="report-status error";els.reportStatus.textContent="此瀏覽器不支援直接分享；教練完整報告已下載，請在 LINE 中選取圖片傳送。"}}catch(error){if(error.name==="AbortError")els.reportStatus.textContent="已取消分享。";else{els.reportStatus.className="report-status error";els.reportStatus.textContent=`分享失敗：${error.message}`}}}

els.overlay.addEventListener("pointerdown",event=>{if(!running||sessionActive||countdownActive)return;const r=els.overlay.getBoundingClientRect();roi={x:event.clientX-r.left,y:event.clientY-r.top,score:1};roiTemplate=null;ctx.clearRect(0,0,els.overlay.clientWidth,els.overlay.clientHeight);drawROI(roi);els.stageGuide.classList.remove("attention");els.stageGuide.textContent="ROI 已設定｜十字為追蹤中心，水平線為上下晃動基準";setQuality("good","ROI 已設定");updateStartAvailability()});
for(const control of[els.buildEndControl,els.stableStartControl,els.stableEndControl,els.shotTimeControl])control.addEventListener("input",updateTimelineFromControls);
els.cameraButton.addEventListener("click",startCamera);els.uploadVideoButton.addEventListener("click",()=>els.videoFileInput.click());els.videoFileInput.addEventListener("change",event=>startUploadedVideo(event.target.files?.[0]));els.rangeStart.addEventListener("input",()=>updateRangeUI("start"));els.rangeEnd.addEventListener("input",()=>updateRangeUI("end"));els.previewStartButton.addEventListener("click",async()=>{if(sourceMode!=="upload"||importBusy||importScanning)return;try{els.video.pause();previewingRange=false;await seekVideo(importedRange.start);els.aiRangeStatus.textContent="已停在選取起點，可點選 ROI 或播放確認。"}catch(error){els.aiRangeStatus.textContent=error.message}});els.previewRangeButton.addEventListener("click",async()=>{if(sourceMode!=="upload"||importBusy||importScanning)return;try{els.video.pause();await seekVideo(importedRange.start);await els.video.play();previewingRange=true;els.aiRangeStatus.textContent="正在播放選取區間…"}catch(error){previewingRange=false;els.aiRangeStatus.textContent=`無法播放：${error.message}`}});els.video.addEventListener("ended",()=>{previewingRange=false;if(sourceMode==="upload"&&sessionActive)finishSession()});els.aiRangeButton.addEventListener("click",suggestImportedRange);els.demoButton.addEventListener("click",startDemo);els.stopCameraButton.addEventListener("click",stopCamera);els.flipButton.addEventListener("click",flipCamera);els.sessionButton.addEventListener("click",startCountdown);els.resetButton.addEventListener("click",resetCalibration);els.reportButton.addEventListener("click",downloadReport);els.shareButton.addEventListener("click",shareReport);els.replayShareButton.addEventListener("click",shareReplay);els.replayDownloadButton.addEventListener("click",downloadReplay);els.exportButton.addEventListener("click",exportCSV);els.helpButton.addEventListener("click",()=>els.helpDialog.showModal());els.closeHelp.addEventListener("click",()=>els.helpDialog.close());els.audienceForm.addEventListener("submit",saveAudience);els.feedbackForm.addEventListener("submit",submitFeedback);els.feedbackEmail.addEventListener("click",emailFeedback);els.audienceDialog.addEventListener("cancel",event=>event.preventDefault());window.addEventListener("resize",resizeOverlay);window.addEventListener("beforeunload",cleanupSource);
$("cameraRetryButton").addEventListener("click",startCamera);
resizeOverlay();drawTrace([]);initUsageStats();showAudienceGate();
